_QQ_ACCENT_NAMES = {
    "(dex)": "dehi",
    "(ger_m)": "geresh muqdam",
    "(mer)": "merkha",
    "(mos)": "meteg or silluq",
    "(mun)": "munah",
    "(ole)": "oleh",
    "(qom)": "qadma or metigah",
    "(tel_g)": "telisha gedolah",
}

_NOTE_QUALIFIER_EXPLANATIONS = {
    "doc-part-n": (
        "The examples in this subsection occur inside a documentation note rather than directly in the running text."
    ),
    "scrdfftar-note": "The examples in this subsection occur inside a scroll-difference note.",
}


def explanation_for_path(path_parts):
    if not path_parts:
        return None
    qualifier = None
    if path_parts[-1] in _NOTE_QUALIFIER_EXPLANATIONS:
        *path_parts, qualifier = path_parts
    base_explanation = _base_explanation_for_path(tuple(path_parts))
    if qualifier is None:
        return base_explanation
    return {
        "label": base_explanation,
        "paras": (_NOTE_QUALIFIER_EXPLANATIONS[qualifier],),
    }


def _base_explanation_for_path(path_parts):
    if path_parts == ("NON_STANDARD_MARK_ORDER",):
        return "that the word's Hebrew combining marks are not in this project's standard internal mark order"
    family, *rest = path_parts
    if family == "qq":
        return _qq_explanation(rest)
    if family == "rare":
        return _rare_explanation(rest)
    if family == "varika":
        return _varika_explanation(rest)
    if family == "xatef-on-non-gutt":
        return _xatef_on_non_gutt_explanation(rest)
    assert False, path_parts


def _qq_explanation(path_parts):
    assert len(path_parts) == 1, path_parts
    accent_code = path_parts[0]
    accent_name = _QQ_ACCENT_NAMES[accent_code]
    return (
        "that the word contains Unicode QAMATS QATAN immediately followed by "
        f"{accent_name}"
    )


def _rare_explanation(path_parts):
    assert len(path_parts) == 1, path_parts
    label = path_parts[0]
    return _RARE_EXPLANATIONS[label]


def _varika_explanation(path_parts):
    if not path_parts:
        return "that the word contains Unicode JUDEO-SPANISH VARIKA"
    assert path_parts == ["two-in-a-word"] or tuple(path_parts) == ("two-in-a-word",)
    return "that the word contains Unicode JUDEO-SPANISH VARIKA twice"


def _xatef_on_non_gutt_explanation(path_parts):
    assert len(path_parts) == 1, path_parts
    return _XATEF_ON_NON_GUTT_EXPLANATIONS[path_parts[0]]


